<?php
function dashboardCacheAcquire(int $uid,int $ttl=15):array{$dir=dirname(__DIR__).'/storage/cache/dashboard';if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))return[null,null];$path=$dir.'/tenant-'.hash('sha256',(string)$uid).'.json';$handle=fopen($path,'c+');if(!$handle)return[null,null];@chmod($path,0600);if(!flock($handle,LOCK_EX)){fclose($handle);return[null,null];}$stat=fstat($handle);if(($stat['mtime']??0)>=time()-$ttl){rewind($handle);$payload=json_decode(stream_get_contents($handle),true);if(is_array($payload)){flock($handle,LOCK_UN);fclose($handle);return[null,$payload];}}return[$handle,null];}
function dashboardCacheStore($handle,array $payload):void{if(!is_resource($handle))return;rewind($handle);ftruncate($handle,0);fwrite($handle,json_encode($payload,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE));fflush($handle);flock($handle,LOCK_UN);fclose($handle);}
